"use strict";var report=function(){$.validator.addMethod("eitherrequired",function(n,t,i){return i.some(function(n){return n.value!==""})});$.validator.unobtrusive.adapters.add("eitherrequired",function(n){var t=$(n.form).find("#HandId")[0],i=$(n.form).find("#Nickname")[0],r=$(n.form).find("#Username")[0];n.rules.eitherrequired=[t,i,r];n.messages.eitherrequired=n.message});var n;return{onSuccess:function(){n&&n.DataTable().clear().destroy();n=$("#report-result table");n.DataTable({ordering:!1,lengthMenu:[100,200,500],language:{emptyTable:"No data"},autoWidth:!1})}}}();